48	\label{eq:alpha-c-theory}
49	\end{equation}
50	where $A = (z^* \sigma / c)^{1/\beta}$ and $z^* = \Phi^{-1}(\pi^*)$ \textup{(proof in Appendix~\ref{app:alpha_c_proof})}.
